"""Concatenate the manual chapters and expand <!-- include: tables/NAME.md --> markers (tables are generated by docs/figures/tables.py).
  uv run python docs/assemble.py docs/build/manual.md"""
import os, re, sys, glob
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(ROOT, "docs", "build", "manual.md")
build = os.path.join(ROOT, "docs", "build")
parts = []
for f in sorted(glob.glob(os.path.join(ROOT, "docs", "manual", "[0-9]*.md"))):
    t = open(f).read()
    def inc(m):
        p = os.path.join(build, m.group(1).strip())
        return open(p).read().strip() if os.path.exists(p) else f"*(missing generated file {m.group(1).strip()}: run `make docs`)*"
    parts.append(re.sub(r"<!--\s*include:\s*(.*?)\s*-->", inc, t))
GLYPHS = {"→": "\\ensuremath{\\rightarrow}", "□": "\\ensuremath{\\square}"}          # glyphs the body font (Helvetica Neue) lacks; code blocks and `code spans` keep the originals (Menlo has them)
def fix_glyphs(text):
    out, fence = [], False
    for line in text.split("\n"):
        if line.lstrip().startswith("```"): fence = not fence; out.append(line); continue
        if fence: out.append(line); continue
        segs = line.split("`")
        for i in range(0, len(segs), 2):
            for k, v in GLYPHS.items(): segs[i] = segs[i].replace(k, v)
        out.append("`".join(segs))
    return "\n".join(out)
def prefer_vector(text):
    """use the vector PDF version of a figure when one exists (figures/<group>/<name>.png -> .pdf)"""
    return re.sub(r"(figures/(?:circuits|system|sims|costs)/[A-Za-z0-9_]+)\.png", lambda m: m.group(1) + (".pdf" if os.path.exists(os.path.join(build, m.group(1) + ".pdf")) else ".png"), text)

def landscape(text):
    """schematics and blueprints get their own landscape page (a stand-alone figure line under figures/circuits or figures/blueprints)"""
    out = []
    for line in text.split("\n"):
        if re.match(r"^!\[.*\]\(figures/(circuits|blueprints)/[^)]+\)\s*$", line): out += ["```{=latex}", "\\begin{landscape}", "```", "", re.sub(r"\)\s*$", "){width=9.6in height=5.7in}", line), "", "```{=latex}", "\\end{landscape}", "```"]
        else: out.append(line)
    return "\n".join(out)

os.makedirs(os.path.dirname(out), exist_ok=True)
open(out, "w").write(landscape(prefer_vector(fix_glyphs("\n\n".join(parts)))) + "\n"); print("assembled", len(parts), "chapters ->", os.path.relpath(out, ROOT))
